import { eq } from "drizzle-orm";
import { db, schema } from "../db/client";

/**
 * Language of texts generated by the server (reports, recap, notices, activity
 * log). Follows the UI language setting (`ui.language`), French by default.
 */
export type Lang = "fr" | "en";

let cached: Lang = "fr";

export async function serverLang(): Promise<Lang> {
  const row = await db.query.settings.findFirst({ where: eq(schema.settings.key, "ui.language") });
  cached = row?.value === "en" ? "en" : "fr";
  return cached;
}

/** Last known language, for synchronous helpers (refreshed by every serverLang() call). */
export function cachedLang(): Lang {
  return cached;
}

/** Pick the string for the language: tx(lang, "Texte", "Text"). */
export function tx(lang: Lang, fr: string, en: string): string {
  return lang === "en" ? en : fr;
}

export function dateLocale(lang: Lang) {
  return lang === "en" ? "en-US" : "fr-FR";
}
